//! Story127.4 ATDD: API and standalone native behavior; ignored until build.
use bitloom_hir::{PortDirection, PortValues};
use bitloom_prelude::{Elaboratable, ElaborateSession, GroundType, Span, ip::CsrDecoder};
use bitloom_sim::{Sim, TickEngine};
use std::collections::BTreeMap;
const LEAVES: [&str; 4] = ["uart", "gpio", "timer", "irq"];
type Values = BTreeMap<String, u64>;
fn ports() -> BTreeMap<String, (PortDirection, GroundType)> {
    use PortDirection::{Input, Output};
    let mut p = BTreeMap::from([
        ("clk".into(), (Input, GroundType::Clock)),
        ("rst".into(), (Input, GroundType::Reset)),
    ]);
    for (n, w, d) in [
        ("req_valid", 1, Input),
        ("write", 1, Input),
        ("addr", 16, Input),
        ("wdata", 32, Input),
        ("wstrb", 4, Input),
        ("rsp_ready", 1, Input),
        ("req_ready", 1, Output),
        ("rsp_valid", 1, Output),
        ("rdata", 32, Output),
        ("error", 2, Output),
    ] {
        p.insert(n.into(), (d, GroundType::UInt { width: w }));
    }
    for leaf in LEAVES {
        for (n, w, d) in [
            ("req_ready", 1, Input),
            ("rsp_valid", 1, Input),
            ("rdata", 32, Input),
            ("error", 2, Input),
            ("req_valid", 1, Output),
            ("write", 1, Output),
            ("addr", 16, Output),
            ("wdata", 32, Output),
            ("wstrb", 4, Output),
            ("rsp_ready", 1, Output),
        ] {
            p.insert(format!("{leaf}_{n}"), (d, GroundType::UInt { width: w }));
        }
    }
    p
}
fn inputs() -> Values {
    ports()
        .into_iter()
        .filter(|(_, (d, _))| *d == PortDirection::Input)
        .map(|(n, _)| (n, 0))
        .collect()
}
fn set(i: &mut Values, name: &str, v: u64) {
    i.insert(name.into(), v);
}
struct Dut(Sim);
impl Dut {
    fn new(engine: TickEngine) -> Self {
        let mut d = Self(Sim::with_engine(CsrDecoder::elaborate().unwrap(), engine));
        let mut i = inputs();
        set(&mut i, "rst", 1);
        d.step(&i);
        d
    }
    fn view(&mut self, i: &Values) -> Values {
        let mut v = PortValues::default();
        for (n, x) in i {
            v.set(n, *x);
        }
        self.0.set_inputs(v);
        self.0.settle();
        ports()
            .into_iter()
            .filter(|(_, (d, _))| *d == PortDirection::Output)
            .map(|(n, _)| {
                let v = self.0.ports().get(&n).unwrap();
                (n, v)
            })
            .collect()
    }
    fn step(&mut self, i: &Values) -> Values {
        let o = self.view(i);
        self.0.tick();
        o
    }
}
// Deliberately independent literal ranges; no production map/helper imported.
fn golden(addr: u64) -> Option<(usize, u64)> {
    if addr <= 0x00ff {
        Some((0, addr))
    } else if (0x0100..=0x01ff).contains(&addr) {
        Some((1, addr - 0x0100))
    } else if (0x0200..=0x02ff).contains(&addr) {
        Some((2, addr - 0x0200))
    } else if (0x0300..=0x03ff).contains(&addr) {
        Some((3, addr - 0x0300))
    } else {
        None
    }
}
fn no_requests(o: &Values) {
    for l in LEAVES {
        assert_eq!(o[&format!("{l}_req_valid")], 0);
    }
}
#[test]
#[ignore = "ATDD RED: activate in Story127.4 build"]
fn p0_exact_52_ports_shared_body_and_definition_reuse() {
    assert_eq!(std::mem::size_of::<CsrDecoder>(), 0);
    let hir = CsrDecoder::elaborate().unwrap();
    let m = &hir.circuit().modules[0];
    assert_eq!(m.ports.len(), 52);
    let actual: BTreeMap<_, _> = m
        .ports
        .iter()
        .map(|p| (p.name.clone(), (p.direction, p.ty.clone())))
        .collect();
    assert_eq!(actual, ports());
    let mut s = ElaborateSession::new("CsrDecoder");
    assert_eq!(
        CsrDecoder::define_module(&mut s, "CsrDecoder").unwrap(),
        "CsrDecoder"
    );
    CsrDecoder::define_module(&mut s, "CsrDecoder").unwrap();
    let shared = s.finish().unwrap();
    assert_eq!(shared.circuit().modules.len(), 1);
    assert_eq!(
        hir, shared,
        "independent and shared entry must use the same body"
    );
    assert_eq!(
        bitloom_vlog::emit(&hir).files[0].contents,
        bitloom_vlog::emit(&shared).files[0].contents
    );
}
#[test]
#[ignore = "ATDD RED: activate in Story127.4 build"]
fn p0_reused_definition_rejects_wrong_connection_width_and_direction() {
    for bad_width in [true, false] {
        let mut s = ElaborateSession::new("Top");
        CsrDecoder::define_module(&mut s, "Decoder").unwrap();
        let span = Span::default();
        s.begin_module("Top", span);
        let mut connects = vec![];
        for (n, (d, ty)) in ports() {
            let ty = if bad_width && n == "addr" {
                GroundType::UInt { width: 8 }
            } else {
                ty
            };
            if d == PortDirection::Input || (!bad_width && n == "req_ready") {
                s.add_input(n.clone(), ty, span);
            } else {
                s.add_output(n.clone(), ty, span);
            }
            connects.push((n.clone(), n));
        }
        s.add_instance("decoder", "Decoder", connects, vec![], span);
        s.end_module();
        assert!(
            !s.finish()
                .expect_err("invalid decoder wiring accepted")
                .0
                .is_empty()
        );
    }
}
#[test]
#[ignore = "ATDD RED: activate in Story127.4 build"]
fn p0_all_65536_addresses_route_actual_dut_without_high_alias_or_alignment() {
    for engine in [TickEngine::Interpreter, TickEngine::Compiled] {
        let mut d = Dut::new(engine);
        let mut i = inputs();
        set(&mut i, "req_valid", 1);
        set(&mut i, "write", 1);
        set(&mut i, "wdata", 0xa55ac33c);
        set(&mut i, "wstrb", 0);
        // No clock edge: exhaustively inspect actual idle combinational routing.
        for addr in 0..=65535 {
            set(&mut i, "addr", addr);
            let o = d.view(&i);
            let g = golden(addr);
            for (j, l) in LEAVES.iter().enumerate() {
                assert_eq!(
                    o[&format!("{l}_req_valid")],
                    u64::from(g.is_some_and(|(k, _)| k == j)),
                    "{engine:?} addr={addr:04x}"
                );
                if let Some((k, local)) = g {
                    if k == j {
                        assert_eq!(o[&format!("{l}_addr")], local);
                        assert_eq!(o[&format!("{l}_write")], 1);
                        assert_eq!(o[&format!("{l}_wdata")], 0xa55ac33c);
                        assert_eq!(o[&format!("{l}_wstrb")], 0);
                    }
                }
            }
            assert_eq!(o["req_ready"], u64::from(g.is_none()));
            assert_eq!(o["rsp_valid"], 0, "DECERR must not be combinational");
        }
    }
}
#[test]
#[ignore = "ATDD RED: activate in Story127.4 build"]
fn p0_owner_survives_long_request_response_stalls_and_input_changes() {
    for engine in [TickEngine::Interpreter, TickEngine::Compiled] {
        for (owner, leaf) in LEAVES.iter().enumerate() {
            let mut d = Dut::new(engine);
            let mut i = inputs();
            for (n, v) in [
                ("req_valid", 1),
                ("addr", owner as u64 * 256 + 255),
                ("write", 1),
                ("wdata", 0xfedc1234),
                ("wstrb", 5),
            ] {
                set(&mut i, n, v);
            }
            for _ in 0..31 {
                let o = d.step(&i);
                assert_eq!(o["req_ready"], 0);
                assert_eq!(o[&format!("{leaf}_req_valid")], 1);
                assert_eq!(o[&format!("{leaf}_addr")], 255);
                assert_eq!(o[&format!("{leaf}_wdata")], 0xfedc1234);
            }
            set(&mut i, &format!("{leaf}_req_ready"), 1);
            let o = d.step(&i);
            assert_eq!(o["req_ready"], 1);
            assert_eq!(o[&format!("{leaf}_req_valid")], 1, "same-edge leaf commit");
            i = inputs();
            // A causal responder can wait without a finite latency guarantee.
            for _ in 0..31 {
                let o = d.step(&i);
                no_requests(&o);
                assert_eq!(o["req_ready"], 0);
                assert_eq!(o["rsp_valid"], 0);
            }
            for l in LEAVES {
                set(&mut i, &format!("{l}_req_ready"), 1);
                set(&mut i, &format!("{l}_rsp_valid"), 1);
                set(&mut i, &format!("{l}_rdata"), 0xdeadbeef);
                set(&mut i, &format!("{l}_error"), 3);
            }
            // Nonowner noise intentionally tests isolation; not claimed as legal peer traffic.
            set(&mut i, &format!("{leaf}_rdata"), 0x1234abcd);
            set(&mut i, &format!("{leaf}_error"), 2);
            for n in 0..31 {
                set(&mut i, "addr", 0x8000 + n);
                set(&mut i, "write", n % 2);
                let o = d.step(&i);
                no_requests(&o);
                assert_eq!((o["rsp_valid"], o["rdata"], o["error"]), (1, 0x1234abcd, 2));
                for l in LEAVES {
                    assert_eq!(o[&format!("{l}_rsp_ready")], 0);
                }
            }
            set(&mut i, "rsp_ready", 1);
            let o = d.step(&i);
            assert_eq!(o["req_ready"], 0);
            for l in LEAVES {
                assert_eq!(o[&format!("{l}_rsp_ready")], u64::from(l == *leaf));
            }
            for _ in 0..8 {
                let o = d.step(&inputs());
                assert_eq!(o["rsp_valid"], 0);
                no_requests(&o);
            }
        }
    }
}
#[test]
#[ignore = "ATDD RED: activate in Story127.4 build"]
fn p0_decerr_is_registered_stable_and_reset_cancels_before_consumption() {
    for engine in [TickEngine::Interpreter, TickEngine::Compiled] {
        for addr in [0x0400, 0x0401, 0x7fff, 0x8000, 0x8104, 0xfffc, 0xffff] {
            let mut d = Dut::new(engine);
            let mut i = inputs();
            set(&mut i, "req_valid", 1);
            set(&mut i, "addr", addr);
            let o = d.step(&i);
            no_requests(&o);
            assert_eq!((o["req_ready"], o["rsp_valid"]), (1, 0));
            i = inputs();
            for n in 0..31 {
                set(&mut i, "addr", n);
                let o = d.step(&i);
                no_requests(&o);
                assert_eq!(
                    (o["req_ready"], o["rsp_valid"], o["error"], o["rdata"]),
                    (0, 1, 3, 0)
                );
            }
            set(&mut i, "rst", 1);
            set(&mut i, "rsp_ready", 1);
            set(&mut i, "req_valid", 1);
            let o = d.step(&i);
            assert_eq!(
                o["rsp_valid"], 1,
                "synchronous reset must not gate response combinationally"
            );
            assert_eq!(o["req_ready"], 0);
            no_requests(&o);
            for l in LEAVES {
                assert_eq!(o[&format!("{l}_rsp_ready")], 0);
            }
            for _ in 0..8 {
                let o = d.step(&inputs());
                assert_eq!(o["rsp_valid"], 0);
            }
            let mut i = inputs();
            set(&mut i, "req_valid", 1);
            set(&mut i, "addr", 0x0204);
            set(&mut i, "timer_req_ready", 1);
            let o = d.step(&i);
            assert_eq!(
                (o["req_ready"], o["timer_req_valid"], o["timer_addr"]),
                (1, 1, 4)
            );
        }
    }
}

//! Story127.4 RED dedicated tool scaffolds. This initial observer covers routing
//! and reset; full causal owner/response observer and mutation suite remain build work.
use bitloom_prelude::{Elaboratable, ip::CsrDecoder};
use std::{
    fs,
    path::{Path, PathBuf},
    process::{Command, Stdio},
    time::Instant,
};
fn design(label: &str) -> (PathBuf, String) {
    let hir = CsrDecoder::elaborate().unwrap();
    let top = hir.circuit().modules[0].name.clone();
    let dir = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../target/fr196-decoder-formal")
        .join(format!("{label}-{}", std::process::id()));
    fs::create_dir_all(&dir).unwrap();
    let rtl = bitloom_vlog::emit(&hir)
        .files
        .iter()
        .map(|f| f.contents.as_str())
        .collect::<Vec<_>>()
        .join("\n");
    fs::write(dir.join("design.v"), rtl).unwrap();
    (dir, top)
}
fn run(dir: &Path, tool: &str, args: &[&str], label: &str) {
    let log = fs::File::create(dir.join(format!("{label}.log"))).unwrap();
    let start = Instant::now();
    let status = Command::new("timeout")
        .args(["--kill-after=5s", "180s", tool])
        .args(args)
        .current_dir(dir)
        .stdout(Stdio::from(log.try_clone().unwrap()))
        .stderr(Stdio::from(log))
        .status()
        .expect("real tool required");
    fs::write(dir.join(format!("{label}-execution.json")),serde_json::json!({"tool":tool,"args":args,"exit_code":status.code(),"elapsed_seconds":start.elapsed().as_secs_f64()}).to_string()).unwrap();
    assert!(
        status.success(),
        "{tool} failed: {status}; {}",
        dir.display()
    );
}
const OBSERVER: &str = r#"
reg f_past=0;
wire [3:0] f_select={irq_req_valid,timer_req_valid,gpio_req_valid,uart_req_valid};
wire [3:0] f_commit={irq_req_valid&&irq_req_ready,timer_req_valid&&timer_req_ready,gpio_req_valid&&gpio_req_ready,uart_req_valid&&uart_req_ready};
always @(posedge clk) begin
  f_past<=1;
  if (!f_past) assume(rst);
  if (f_past) begin
    assert((f_select & (f_select-1'b1)) == 0);
    if (rst) begin
      assert(!req_ready && f_select==0);
      assert(!uart_rsp_ready && !gpio_rsp_ready && !timer_rsp_ready && !irq_rsp_ready);
    end else begin
      if ($past(!rst && req_valid && !req_ready)) begin
        assume(req_valid);
        assume({write,addr,wdata,wstrb}==$past({write,addr,wdata,wstrb}));
      end
      if (addr>=16'h0400) assert(f_select==0);
      if (req_valid && req_ready) begin
        if (addr<16'h0400) assert(f_commit!=0); else assert(f_commit==0);
      end
      if (f_commit!=0) assert(req_valid && req_ready);
      if (uart_req_valid) begin
        assert(addr<=16'h00ff); assert(uart_addr==addr);
        assert({uart_write,uart_wdata,uart_wstrb}=={write,wdata,wstrb});
      end
      if (gpio_req_valid) begin
        assert(addr>=16'h0100 && addr<=16'h01ff); assert(gpio_addr==addr-16'h0100);
        assert({gpio_write,gpio_wdata,gpio_wstrb}=={write,wdata,wstrb});
      end
      if (timer_req_valid) begin
        assert(addr>=16'h0200 && addr<=16'h02ff); assert(timer_addr==addr-16'h0200);
        assert({timer_write,timer_wdata,timer_wstrb}=={write,wdata,wstrb});
      end
      if (irq_req_valid) begin
        assert(addr>=16'h0300 && addr<=16'h03ff); assert(irq_addr==addr-16'h0300);
        assert({irq_write,irq_wdata,irq_wstrb}=={write,wdata,wstrb});
      end
      cover(f_commit[0]); cover(f_commit[1]); cover(f_commit[2]); cover(f_commit[3]);
      cover(req_valid && req_ready && addr==16'hffff);
    end
  end
end
"#;
#[test]
#[ignore = "ATDD RED: activate in Story127.4 build; requires real SBY/Yosys/Z3"]
fn p0_initial_port_only_routing_reset_prove_and_cover() {
    let (dir, top) = design("routing");
    run(&dir, "yosys", &["-V"], "yosys-version");
    run(&dir, "sby", &["--version"], "sby-version");
    run(&dir, "z3", &["--version"], "z3-version");
    let rtl = fs::read_to_string(dir.join("design.v")).unwrap();
    assert_eq!(rtl.matches("endmodule").count(), 1);
    fs::write(
        dir.join("observed.v"),
        rtl.replace("endmodule", &format!("{OBSERVER}\nendmodule")),
    )
    .unwrap();
    for mode in ["prove", "cover"] {
        fs::write(dir.join(format!("{mode}.sby")),format!("[options]\nmode {mode}\ndepth 8\n[engines]\nsmtbmc --unroll z3\n[script]\nread -formal observed.v\nprep -top {top}\n[files]\nobserved.v\n")).unwrap();
        run(&dir, "sby", &["-f", &format!("{mode}.sby")], mode);
        let status = fs::read_to_string(dir.join(mode).join("status")).unwrap();
        assert_eq!(status.split_whitespace().next(), Some("PASS"));
    }
}
#[test]
#[ignore = "ATDD RED: activate in Story127.4 build; requires real Yosys"]
fn p0_original_decoder_synthesis_check() {
    let (dir, top) = design("synthesis");
    run(&dir, "yosys", &["-V"], "yosys-version");
    let script = format!(
        "read_verilog design.v; hierarchy -check -top {top}; proc; check -assert; synth -top {top}; check -assert; stat; write_json synthesis.json"
    );
    run(&dir, "yosys", &["-p", &script], "synthesis");
    let net: serde_json::Value =
        serde_json::from_str(&fs::read_to_string(dir.join("synthesis.json")).unwrap()).unwrap();
    let cells = net["modules"][&top]["cells"].as_object().unwrap();
    assert!(!cells.is_empty());
    for cell in cells.values() {
        let kind = cell["type"].as_str().unwrap();
        assert!(!kind.to_ascii_lowercase().contains("latch"), "latch {kind}");
    }
}
